(() => {
 'use strict';
 const $=s=>document.querySelector(s), e=window.IGUI.escape, icon=window.IGUI.icon;
 const page=document.querySelector('[data-blog-page]')?.dataset.blogPage;
 const covers={golf:'assets/volkswagen-golf-sportsvan.jpg',jaguar:'assets/jaguar-e-pace.jpg',peugeot:'assets/peugeot-308-gt.jpg'};
 const date=value=>new Intl.DateTimeFormat('pl-PL',{day:'numeric',month:'long',year:'numeric'}).format(new Date(value));
 async function api(path,options={}){const response=await fetch('/api/blog/'+path,{...options,headers:{...(options.method?{'Content-Type':'application/json'}:{}),...options.headers}});let data;try{data=await response.json();}catch{throw new Error('Nie udało się połączyć z blogiem. Odśwież stronę lub spróbuj ponownie później.');}if(!response.ok)throw Object.assign(new Error(data.error||'Nie udało się wykonać operacji.'),{status:response.status});return data;}
 function paragraphs(container,text){container.replaceChildren();text.split(/\n\n+/).filter(Boolean).forEach(part=>{const heading=part.startsWith('## ');const node=document.createElement(heading?'h2':'p');node.textContent=heading?part.slice(3):part;container.append(node);});}
 function card(post){return `<article class="blog-card"><a class="blog-card-photo" href="wpis.html?id=${encodeURIComponent(post.id)}"><img src="${covers[post.cover]||covers.golf}" alt="Okładka artykułu" loading="lazy"><span>${e(post.category)}</span></a><div class="blog-card-body"><div class="blog-meta"><span>${e(date(post.publishedAt))}</span><span>${e(post.author)}</span>${post.example?'<span>Wpis przykładowy</span>':''}</div><h2><a href="wpis.html?id=${encodeURIComponent(post.id)}">${e(post.title)}</a></h2><p>${e(post.excerpt)}</p><a class="text-link" href="wpis.html?id=${encodeURIComponent(post.id)}">Przeczytaj artykuł ${icon('arrow')}</a></div></article>`;}
 function preview(post){const container=$('#blog-preview-content');container.innerHTML=`<div class="blog-preview-heading"><span class="blog-kicker">PODGLĄD WPISU</span><h1>${e(post.title||'Tytuł Twojego wpisu')}</h1><p class="blog-meta">${e(post.author||'Autor')} · ${e(post.category||'Motoryzacja')}</p><p class="article-lead">${e(post.excerpt||'Wprowadzenie do artykułu')}</p></div><img class="blog-preview-cover" src="${covers[post.cover]||covers.golf}" alt="Wybrana okładka"><div class="article-body" id="preview-article-body"></div>`;paragraphs($('#preview-article-body'),post.content||'Treść Twojego wpisu');$('#blog-preview-dialog').showModal();document.body.classList.add('dialog-open');}
 const dialog=$('#blog-preview-dialog');if(dialog){$('.blog-dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});}
 if(page==='list'){
  let request=0;let timer;
  async function load(){const number=++request;const query=new URLSearchParams();if($('#blog-search').value.trim())query.set('q',$('#blog-search').value.trim());if($('#blog-category').value)query.set('category',$('#blog-category').value);try{const data=await api('posts?'+query);if(number!==request)return;$('#blog-posts').innerHTML=data.posts.map(card).join('');$('#blog-empty').hidden=data.posts.length>0;$('#blog-list-status').textContent='';}catch(error){if(number===request)$('#blog-list-status').textContent=error.message;}}
  $('#blog-search').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(load,250);});$('#blog-category').addEventListener('change',load);load();
 }
 if(page==='article'){
  const sample=JSON.parse($('#blog-example-data').textContent);const id=new URLSearchParams(location.search).get('id')||sample.id;
  if(id!==sample.id)api('posts/'+encodeURIComponent(id)).then(({post})=>{document.title=post.title+' — IG Motors';$('#article-title').textContent=post.title;$('#article-excerpt').textContent=post.excerpt;$('#article-author').textContent=post.author;$('#article-category').textContent=post.category;$('#article-date').textContent=date(post.publishedAt);$('#article-example').hidden=true;$('#article-cover').src=covers[post.cover]||covers.golf;paragraphs($('#article-body'),post.content);}).catch(error=>{$('#article-status').textContent=error.message;$('#blog-article').hidden=true;});
 }
 if(page==='submit'){
  const form=$('#blog-submit-form');let token='';let saved=false;
  const value=()=>Object.fromEntries(new FormData(form));
  api('context').then(data=>{token=data.submissionToken;$('#blog-submit').disabled=!data.canSubmit;$('#blog-form-status').textContent='Gotowe. Twój wpis pojawi się na blogu po zatwierdzeniu przez redakcję.';}).catch(error=>{$('#blog-form-status').textContent=error.message;});
  $('#blog-content').addEventListener('input',()=>{$('#blog-char-count').textContent=$('#blog-content').value.length.toLocaleString('pl-PL');});
  $('#blog-preview').addEventListener('click',()=>preview(value()));
  form.addEventListener('submit',async event=>{event.preventDefault();if(saved||!token||!form.reportValidity())return;const post=value();post.consent=form.elements.consent.checked;post.submissionToken=token;$('#blog-submit').disabled=true;$('#blog-form-status').textContent='Zapisujemy Twój wpis…';try{const result=await api('submissions',{method:'POST',body:JSON.stringify(post)});saved=true;$('#blog-form-status').textContent=result.message;$('#blog-success').hidden=false;form.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=true);$('#blog-success').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});}catch(error){$('#blog-form-status').textContent=error.message;$('#blog-submit').disabled=false;if(error.status===403){try{token=(await api('context')).submissionToken;$('#blog-form-status').textContent+=' Sesja została odświeżona; wyślij wpis ponownie.';}catch{}}}});
 }
 if(page==='admin'){
  let state='pending',token='',posts=[],loadSequence=0;
  async function load(){const sequence=++loadSequence;try{const data=await api('admin/posts?status='+state);if(sequence!==loadSequence)return;posts=data.posts;document.querySelectorAll('[data-count]').forEach(el=>el.textContent=data.counts[el.dataset.count]||0);$('#blog-admin-posts').innerHTML=posts.map(post=>`<article class="blog-admin-card"><div class="blog-meta"><span>${e(post.category)}</span><span>${e(date(post.createdAt))}</span><span>${e(post.author)}</span></div><h2>${e(post.title)}</h2><p>${e(post.excerpt)}</p><div class="blog-admin-actions"><button type="button" class="button button-outline" data-preview-post="${post.id}">Przeczytaj całość ${icon('search')}</button>${state!=='published'?`<button type="button" class="button button-red" data-moderate="published" data-post-id="${post.id}">Opublikuj ${icon('check')}</button>`:`<a class="text-link" href="wpis.html?id=${post.id}">Otwórz wpis ${icon('arrow-up')}</a><button type="button" class="blog-admin-secondary" data-moderate="pending" data-post-id="${post.id}">Wycofaj do oczekujących</button>`}${state!=='rejected'?`<button type="button" class="blog-admin-secondary" data-moderate="rejected" data-post-id="${post.id}">Odrzuć</button>`:''}</div></article>`).join('');$('#blog-admin-empty').hidden=posts.length>0;}catch(error){$('#blog-admin-status').textContent=error.message;}}
  api('context').then(data=>{if(!data.canModerate){if(data.signedIn){$('#blog-admin-status').textContent='To konto nie ma dostępu do panelu redakcji.';}else $('#blog-admin-status').textContent='Zaloguj się, aby zarządzać zgłoszeniami.';return;}token=data.submissionToken;$('#blog-admin-auth').hidden=true;$('#blog-admin-panel').hidden=false;$('#blog-admin-status').textContent='';load();}).catch(error=>{$('#blog-admin-status').textContent=error.message;});
  document.querySelectorAll('[data-post-status]').forEach(button=>button.addEventListener('click',()=>{state=button.dataset.postStatus;document.querySelectorAll('[data-post-status]').forEach(el=>{el.classList.toggle('selected',el===button);el.setAttribute('aria-pressed',String(el===button));});load();}));
  $('#blog-admin-posts').addEventListener('click',async event=>{const previewButton=event.target.closest('[data-preview-post]');if(previewButton){const post=posts.find(p=>p.id===previewButton.dataset.previewPost);if(post)preview(post);return;}const button=event.target.closest('[data-moderate]');if(!button)return;button.disabled=true;try{await api('admin/posts/'+encodeURIComponent(button.dataset.postId),{method:'PATCH',body:JSON.stringify({status:button.dataset.moderate,submissionToken:token})});$('#blog-admin-status').textContent=button.dataset.moderate==='published'?'Wpis został opublikowany.':button.dataset.moderate==='rejected'?'Zgłoszenie zostało odrzucone.':'Wpis został przeniesiony do oczekujących.';await load();}catch(error){button.disabled=false;$('#blog-admin-status').textContent=error.message;if(error.status===403){try{token=(await api('context')).submissionToken;}catch{}}}});
 }
})();
